namespace QuickCode.QuickCode.Infrastructure.Web.Filters;

public sealed class KafkaPublishFilter : IAsyncActionFilter
{
    private readonly IKafkaEventCatalog _catalog;
    private readonly IKafkaProducerWrapper _producer;

    public KafkaPublishFilter(IKafkaEventCatalog catalog, IKafkaProducerWrapper producer)
