        var kafkaEvent = await _catalog.FindAsync(http.Request.Method, path);
        if (kafkaEvent is null && http.Request.PathBase.HasValue)
            kafkaEvent = await _catalog.FindAsync(http.Request.Method, $"{http.Request.PathBase.Value}{path}");
        if (kafkaEvent is null)
        {
            await next();
            return;
        }

        var stopwatch = Stopwatch.StartNew();
        var executed = await next();
        stopwatch.Stop();

        await PublishSafeAsync(context, executed, kafkaEvent.TopicName, stopwatch.ElapsedMilliseconds);
    }

    private async Task PublishSafeAsync(
        ActionExecutingContext executing,
        ActionExecutedContext executed,
        string topic,
        long elapsedMs)
    {
        try
        {
            var http = executed.HttpContext;
            var statusCode = executed.Result is ObjectResult objectResult && objectResult.StatusCode.HasValue
                ? objectResult.StatusCode.Value
                : http.Response.StatusCode;

            var kafkaMessage = new KafkaMessage
            {
                RequestInfo = new RequestInfo
                {
                    Path = http.Request.Path,
                    Method = http.Request.Method,
                    Headers = http.Request.Headers.ToDictionary(h => h.Key, h => h.Value.ToString()),
                    Body = ConvertToJsonObject(executing.ActionArguments.ToJson())
                },
                ResponseInfo = new ResponseInfo
                {
                    StatusCode = statusCode,
                    Headers = http.Response.Headers.ToDictionary(h => h.Key, h => h.Value.ToString()),
                    Body = ConvertToJsonObject(SerializeResult(executed))
                },
                ExceptionMessage = executed.Exception?.Message ?? string.Empty,
                ElapsedMilliseconds = (int)elapsedMs,
                Timestamp = DateTime.UtcNow
            };

            var key = $"{http.Request.Method}|{http.Request.Path}|{DateTime.UtcNow.Ticks}";
            var payload = JsonConvert.SerializeObject(kafkaMessage, new JsonSerializerSettings
            {
                NullValueHandling = NullValueHandling.Include
            });
            await _producer.ProduceAsync(topic, key, payload);
            Log.Information("Kafka message sent. Topic={Topic} Key={Key}", topic, key);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Kafka publish failed. Topic={Topic} Path={Path}", topic, executing.HttpContext.Request.Path);
        }
