    private static string SerializeResult(ActionExecutedContext executed)
    {
        if (executed.Exception != null)
            return new JObject { ["message"] = "An error occurred." }.ToString();

        return executed.Result switch
        {
            ObjectResult objectResult => objectResult.Value.ToJson(),
            JsonResult jsonResult => jsonResult.Value.ToJson(),
            _ => string.Empty
